TASA_IVA = 0.13


def precio_con_iva(precio, tasa=TASA_IVA):
    """Devuelve el precio con impuesto, redondeado a colones."""
    return round(precio * (1 + tasa))


def costo_envio(provincia, monto):
    """Envío gratis desde ₡50 000; si no, ₡2 500 en el Valle Central y ₡3 500 en las costas."""
    if monto >= 50000:
        return 0
    provincia = provincia.strip().lower()
    if provincia == "san josé" or provincia == "alajuela" or provincia == "cartago" or provincia == "heredia":
        return 2500
    return 3500


print(precio_con_iva(6500))
print(precio_con_iva(6500, tasa=0.01))
