CREATE TABLE tarifas_envio (
  provincia_id INTEGER PRIMARY KEY REFERENCES provincias(id),
  tarifa INTEGER NOT NULL DEFAULT 2500
);
INSERT INTO tarifas_envio (provincia_id)
SELECT id FROM provincias;
UPDATE tarifas_envio
SET tarifa = 3500
WHERE provincia_id IN (
  SELECT id FROM provincias
  WHERE nombre IN ('Guanacaste', 'Puntarenas', 'Limón')
);

